/*
 * database.hpp — Clause database for the Epilog inference engine.
 * JPL rules: no recursion, bounded capacities, no post-init malloc.
 */

#pragma once

#include <cstdint>
#include "atoms.hpp"
#include "terms.hpp"
#include "parser.hpp"

constexpr uint32_t DB_MAX_PREDICATES  = 512U;
constexpr uint32_t DB_MAX_CLAUSES     = 4096U;
constexpr uint32_t DB_MAX_BODY_GOALS  = PARSER_MAX_BODY_GOALS;

/* ---- First-argument index ------------------------------------------------- */

/*
 * Each predicate of arity >= 1 maintains an index over the first argument.
 * Clauses whose first arg is a ground atom or integer are placed in a bucket
 * keyed by that value.  Clauses whose first arg is a variable go into the
 * catch-all bucket (idx_var_*) and are always tried regardless of the query.
 *
 * Bucket layout (parallel arrays, indexed 0..idx_bucket_count-1):
 *   idx_key[]      — atom_id (INDEX_KEY_KIND_ATOM) or int32 (INDEX_KEY_KIND_INT)
 *   idx_kind[]     — discriminator
 *   idx_start[]    — first slot in idx_clause_slots[] for this bucket
 *   idx_count[]    — number of clause indices in this bucket
 * idx_clause_slots — flat list of clause positions (into db->clauses[])
 */

constexpr uint32_t INDEX_MAX_BUCKETS       = 64U;
constexpr uint32_t INDEX_MAX_INDEXED       = 256U;  /* max indexed clauses per pred */
constexpr uint32_t INDEX_MAX_VAR_CLAUSES   = 64U;   /* max catch-all var clauses */

enum IndexKeyKind : uint8_t {
    INDEX_KEY_ATOM = 0,
    INDEX_KEY_INT  = 1
};

union IndexKey {
    AtomId  atom_id;
    int32_t int_val;
};

struct FirstArgIndex {
    /* Ground buckets */
    IndexKey     idx_key[INDEX_MAX_BUCKETS]   = {};
    IndexKeyKind idx_kind[INDEX_MAX_BUCKETS]  = {};
    uint32_t     idx_start[INDEX_MAX_BUCKETS] = {};
    uint32_t     idx_count[INDEX_MAX_BUCKETS] = {};
    uint32_t     idx_bucket_count             = 0U;

    /* Flat clause-position list (ground buckets share this pool) */
    uint32_t     idx_clause_slots[INDEX_MAX_INDEXED] = {};
    uint32_t     idx_slot_count                       = 0U;

    /* Variable (catch-all) clauses */
    uint32_t     idx_var_slots[INDEX_MAX_VAR_CLAUSES] = {};
    uint32_t     idx_var_count                         = 0U;

    bool         built = false;   /* true once index has been constructed */
};

/* ---- Stored clause -------------------------------------------------------- */

using ClauseId = uint32_t;
constexpr ClauseId CLAUSE_ID_INVALID = 0U;

struct StoredClause {
    TermRef  head    = TERM_REF_INVALID;
    TermRef  body[DB_MAX_BODY_GOALS] = {};
    uint32_t body_len = 0U;
    ClauseId id       = CLAUSE_ID_INVALID;
};

/* ---- Predicate entry ------------------------------------------------------ */

struct PredEntry {
    AtomId        functor = ATOM_ID_INVALID;
    uint8_t       arity   = 0U;
    uint32_t      first   = 0U;
    uint32_t      count   = 0U;
    FirstArgIndex index   = {};
};

/* ---- Database ------------------------------------------------------------- */

struct Database {
    StoredClause clauses[DB_MAX_CLAUSES];
    uint32_t     clause_count = 0U;
    PredEntry    preds[DB_MAX_PREDICATES];
    uint32_t     pred_count   = 0U;
};

int                 db_init(Database *db);
int                 db_assert_last(Database *db, const ParsedClause *clause,
                                   TermArena *arena);
int                 db_retract_first(Database *db, AtomId functor, uint8_t arity);
const PredEntry    *db_get_pred(const Database *db, AtomId functor, uint8_t arity);
const StoredClause *db_get_clause(const Database *db, uint32_t idx);

/*
 * db_build_index — (re)build the first-argument index for a predicate.
 * Called internally after assert/retract; exposed for testing.
 */
void db_build_index(PredEntry *pred, const Database *db, const TermArena *arena);

/*
 * db_index_range — fill out[0..max) with clause positions matching first_arg.
 * Returns count written.  Falls back to returning all clauses if index not built
 * or arity == 0.
 */
uint32_t db_index_range(const PredEntry *pred, const Database *db,
                        const TermArena *arena, const VarRegistry *vars,
                        TermRef first_arg,
                        uint32_t *out, uint32_t max_out);

/*
 * database.cpp — Clause database implementation.
 * JPL rules: no recursion, bounded loops, no post-init malloc.
 */

#include "../include/database.hpp"
#include <cstring>
#include <cassert>

/* ---- Internal helpers ----------------------------------------------------- */

static PredEntry *find_pred(Database *db, AtomId functor, uint8_t arity)
{
    assert(db != nullptr);
    for (uint32_t i = 0U; i < db->pred_count; ++i) {
        if (db->preds[i].functor == functor && db->preds[i].arity == arity) {
            return &db->preds[i];
        }
    }
    return nullptr;
}

static PredEntry *find_or_create_pred(Database *db, AtomId functor, uint8_t arity)
{
    PredEntry *e = find_pred(db, functor, arity);
    if (e != nullptr) { return e; }
    if (db->pred_count >= DB_MAX_PREDICATES) { return nullptr; }

    e = &db->preds[db->pred_count];
    memset(e, 0, sizeof(PredEntry));
    e->functor = functor;
    e->arity   = arity;
    e->first   = db->clause_count;
    e->count   = 0U;
    db->pred_count++;
    return e;
}

/* ---- First-argument index ------------------------------------------------- */

void db_build_index(PredEntry *pred, const Database *db, const TermArena *arena)
{
    assert(pred != nullptr && db != nullptr && arena != nullptr);

    FirstArgIndex *idx = &pred->index;
    memset(idx, 0, sizeof(FirstArgIndex));

    if (pred->arity == 0U || pred->count == 0U) {
        idx->built = true;
        return;
    }

    for (uint32_t ci = 0U; ci < pred->count; ++ci) {
        const uint32_t abs_pos = pred->first + ci;
        const StoredClause *sc = db_get_clause(db, abs_pos);
        if (sc == nullptr) { continue; }

        const Term *head = term_get(arena, sc->head);
        if (head == nullptr) { continue; }

        /* Extract the first argument of the head term */
        TermRef first_arg_ref = TERM_REF_INVALID;
        if (head->kind == TERM_KIND_COMPOUND && head->data.compound.arity >= 1U) {
            first_arg_ref = term_arg(arena, sc->head, 0U);
        }

        const Term *fa = (first_arg_ref != TERM_REF_INVALID)
                         ? term_get(arena, first_arg_ref) : nullptr;

        bool is_ground = false;
        IndexKeyKind kind = INDEX_KEY_ATOM;
        IndexKey     key  = {};

        if (fa != nullptr) {
            if (fa->kind == TERM_KIND_ATOM) {
                is_ground = true;
                kind      = INDEX_KEY_ATOM;
                key.atom_id = fa->data.atom_id;
            } else if (fa->kind == TERM_KIND_INT) {
                is_ground = true;
                kind      = INDEX_KEY_INT;
                key.int_val = fa->data.int_val;
            }
        }

        if (!is_ground) {
            /* Variable first arg — goes into catch-all */
            if (idx->idx_var_count < INDEX_MAX_VAR_CLAUSES) {
                idx->idx_var_slots[idx->idx_var_count++] = abs_pos;
            }
            continue;
        }

        /* Find or create a bucket for this key */
        uint32_t bucket = INDEX_MAX_BUCKETS; /* sentinel: not found */
        for (uint32_t bi = 0U; bi < idx->idx_bucket_count; ++bi) {
            if (idx->idx_kind[bi] != kind) { continue; }
            if (kind == INDEX_KEY_ATOM && idx->idx_key[bi].atom_id == key.atom_id) {
                bucket = bi; break;
            }
            if (kind == INDEX_KEY_INT  && idx->idx_key[bi].int_val == key.int_val) {
                bucket = bi; break;
            }
        }

        if (bucket == INDEX_MAX_BUCKETS) {
            if (idx->idx_bucket_count >= INDEX_MAX_BUCKETS) {
                /* Overflow: fall back gracefully — treat as var clause */
                if (idx->idx_var_count < INDEX_MAX_VAR_CLAUSES) {
                    idx->idx_var_slots[idx->idx_var_count++] = abs_pos;
                }
                continue;
            }
            bucket = idx->idx_bucket_count;
            idx->idx_kind[bucket]  = kind;
            idx->idx_key[bucket]   = key;
            idx->idx_start[bucket] = idx->idx_slot_count;
            idx->idx_count[bucket] = 0U;
            idx->idx_bucket_count++;
        }

        if (idx->idx_slot_count < INDEX_MAX_INDEXED) {
            /* Append the slot — NOTE: we rely on buckets being built in clause
             * order and appended contiguously. Because we iterate ci in order
             * and always append, idx_start..idx_start+idx_count is contiguous
             * within idx_clause_slots[]. */
            idx->idx_clause_slots[idx->idx_slot_count++] = abs_pos;
            idx->idx_count[bucket]++;
        }
    }

    idx->built = true;
}

uint32_t db_index_range(const PredEntry *pred, const Database *db,
                        const TermArena *arena, const VarRegistry *vars,
                        TermRef first_arg,
                        uint32_t *out, uint32_t max_out)
{
    (void)db;
    if (pred == nullptr || out == nullptr || max_out == 0U) { return 0U; }

    /* No index available or arity == 0 — return all clauses */
    const FirstArgIndex *idx = &pred->index;
    if (!idx->built || pred->arity == 0U) {
        uint32_t n = pred->count < max_out ? pred->count : max_out;
        for (uint32_t i = 0U; i < n; ++i) { out[i] = pred->first + i; }
        return n;
    }

    /* Dereference the first argument to see if it's ground */
    const Term *fa = nullptr;
    if (first_arg != TERM_REF_INVALID && arena != nullptr) {
        /* Walk variable chain */
        TermRef ref = first_arg;
        if (vars != nullptr) {
            for (uint32_t step = 0U; step < VAR_REGISTRY_CAPACITY; ++step) {
                const Term *t = term_get(arena, ref);
                if (t == nullptr) break;
                if (t->kind != TERM_KIND_VAR) { fa = t; break; }
                WalkResult wr = var_walk(vars, t->data.var.var_id);
                if (wr.tag == TERM_UNBOUND) { break; }
                if (wr.tag == TERM_TERMREF) { ref = wr.value.term_ref; }
                else { break; }
            }
        } else {
            fa = term_get(arena, ref);
        }
    }

    bool is_ground = false;
    IndexKeyKind kind = INDEX_KEY_ATOM;
    IndexKey     key  = {};

    if (fa != nullptr) {
        if (fa->kind == TERM_KIND_ATOM) {
            is_ground = true; kind = INDEX_KEY_ATOM; key.atom_id = fa->data.atom_id;
        } else if (fa->kind == TERM_KIND_INT) {
            is_ground = true; kind = INDEX_KEY_INT;  key.int_val = fa->data.int_val;
        }
    }

    if (!is_ground) {
        /* Variable query: must try all clauses (ground buckets + var bucket) */
        uint32_t n = pred->count < max_out ? pred->count : max_out;
        for (uint32_t i = 0U; i < n; ++i) { out[i] = pred->first + i; }
        return n;
    }

    /* Ground query: find matching bucket, then merge with var clauses.
     * We merge them in clause order (ascending absolute position). */
    uint32_t bucket = INDEX_MAX_BUCKETS;
    for (uint32_t bi = 0U; bi < idx->idx_bucket_count; ++bi) {
        if (idx->idx_kind[bi] != kind) { continue; }
        if (kind == INDEX_KEY_ATOM && idx->idx_key[bi].atom_id == key.atom_id) {
            bucket = bi; break;
        }
        if (kind == INDEX_KEY_INT  && idx->idx_key[bi].int_val == key.int_val) {
            bucket = bi; break;
        }
    }

    /* Merge: ground bucket entries + var entries, sorted by clause position */
    uint32_t gi = 0U, vi = 0U;
    uint32_t g_count = (bucket < INDEX_MAX_BUCKETS) ? idx->idx_count[bucket] : 0U;
    uint32_t g_start = (bucket < INDEX_MAX_BUCKETS) ? idx->idx_start[bucket] : 0U;
    uint32_t v_count = idx->idx_var_count;
    uint32_t written = 0U;

    while ((gi < g_count || vi < v_count) && written < max_out) {
        uint32_t gpos = (gi < g_count) ? idx->idx_clause_slots[g_start + gi] : UINT32_MAX;
        uint32_t vpos = (vi < v_count) ? idx->idx_var_slots[vi]              : UINT32_MAX;
        if (gpos <= vpos) { out[written++] = gpos; gi++; }
        else              { out[written++] = vpos; vi++; }
    }
    return written;
}

/* ---- Public API ----------------------------------------------------------- */

int db_init(Database *db)
{
    if (db == nullptr) { return -1; }
    memset(db, 0, sizeof(Database));
    return 0;
}

int db_assert_last(Database *db, const ParsedClause *clause, TermArena *arena)
{
    if (db == nullptr || clause == nullptr) { return -1; }
    if (db->clause_count >= DB_MAX_CLAUSES) { return -1; }

    const Term *head_term = term_get(arena, clause->head);
    if (head_term == nullptr) { return -1; }

    AtomId  functor;
    uint8_t arity;

    switch (head_term->kind) {
        case TERM_KIND_ATOM:
            functor = head_term->data.atom_id;
            arity   = 0U;
            break;
        case TERM_KIND_COMPOUND:
            functor = head_term->data.compound.functor;
            arity   = head_term->data.compound.arity;
            break;
        default:
            return -1;
    }

    PredEntry *pred = find_or_create_pred(db, functor, arity);
    if (pred == nullptr) { return -1; }

    const uint32_t insert_pos = pred->first + pred->count;

    for (uint32_t shift = db->clause_count; shift > insert_pos; --shift) {
        db->clauses[shift]    = db->clauses[shift - 1U];
        db->clauses[shift].id = static_cast<ClauseId>(shift + 1U);
    }

    for (uint32_t pi = 0U; pi < db->pred_count; ++pi) {
        if (&db->preds[pi] != pred && db->preds[pi].first >= insert_pos) {
            db->preds[pi].first++;
        }
    }

    StoredClause *sc = &db->clauses[insert_pos];
    memset(sc, 0, sizeof(StoredClause));
    sc->head     = clause->head;
    sc->body_len = clause->body_len;
    sc->id       = static_cast<ClauseId>(insert_pos + 1U);

    assert(clause->body_len <= DB_MAX_BODY_GOALS);
    for (uint32_t bi = 0U; bi < clause->body_len; ++bi) {
        sc->body[bi] = clause->body[bi];
    }

    pred->count++;
    db->clause_count++;

    /* Rebuild index for this predicate */
    db_build_index(pred, db, arena);

    return 0;
}

int db_retract_first(Database *db, AtomId functor, uint8_t arity)
{
    if (db == nullptr || functor == ATOM_ID_INVALID) { return -1; }

    PredEntry *pred = find_pred(db, functor, arity);
    if (pred == nullptr || pred->count == 0U) { return -1; }

    const uint32_t remove_pos = pred->first;

    for (uint32_t shift = remove_pos; shift + 1U < db->clause_count; ++shift) {
        db->clauses[shift]    = db->clauses[shift + 1U];
        db->clauses[shift].id = static_cast<ClauseId>(shift + 1U);
    }
    db->clause_count--;
    pred->count--;

    for (uint32_t pi = 0U; pi < db->pred_count; ++pi) {
        if (&db->preds[pi] != pred && db->preds[pi].first > remove_pos) {
            db->preds[pi].first--;
        }
    }

    /* Index is now stale — mark invalid so solver falls back to linear scan.
     * We can't rebuild without the arena pointer here, so we clear it. */
    pred->index.built = false;

    return 0;
}

const PredEntry *db_get_pred(const Database *db, AtomId functor, uint8_t arity)
{
    if (db == nullptr || functor == ATOM_ID_INVALID) { return nullptr; }
    for (uint32_t i = 0U; i < db->pred_count; ++i) {
        if (db->preds[i].functor == functor && db->preds[i].arity == arity) {
            return &db->preds[i];
        }
    }
    return nullptr;
}

const StoredClause *db_get_clause(const Database *db, uint32_t idx)
{
    if (db == nullptr || idx >= db->clause_count) { return nullptr; }
    return &db->clauses[idx];
}

/*
 * solver.cpp — Backtracking SLD resolution engine.
 * JPL rules: no C recursion, bounded stacks, no post-init malloc.
 */

#include "../include/solver.hpp"
#include "../include/builtins.hpp"
#include "../include/log.hpp"
#include <cstring>
#include <cassert>

/* ---- Internal frame types ------------------------------------------------- */

struct GoalStack {
    TermRef  goals[GOAL_STACK_CAPACITY];
    uint32_t top = 0U;
};

/*
 * ChoicePoint now stores an explicit candidate list (up to INDEX_MAX_INDEXED +
 * INDEX_MAX_VAR_CLAUSES positions) instead of a contiguous pred->first..end
 * range.  This lets the first-argument index prune the candidate set at the
 * point a choice is created.
 */
constexpr uint32_t CP_MAX_CANDIDATES = INDEX_MAX_INDEXED + INDEX_MAX_VAR_CLAUSES;

struct ChoicePoint {
    uint32_t candidates[CP_MAX_CANDIDATES];
    uint32_t cand_count;
    uint32_t cand_idx;     /* next candidate to try */
    TermRef  goal;
    uint32_t trail_mark;
    uint32_t goal_top;
};

struct ChoiceStack {
    ChoicePoint items[CHOICE_STACK_CAPACITY];
    uint32_t    top = 0U;
};

/* ---- Variable rename map -------------------------------------------------- */

constexpr uint32_t RENAME_MAP_CAP = VAR_REGISTRY_CAPACITY;

struct RenameMap {
    VarId    old_id[RENAME_MAP_CAP];
    VarId    new_id[RENAME_MAP_CAP];
    uint32_t count = 0U;
};

static VarId rename_lookup(const RenameMap *rm, VarId old)
{
    for (uint32_t i = 0U; i < rm->count; ++i) {
        if (rm->old_id[i] == old) { return rm->new_id[i]; }
    }
    return VAR_ID_INVALID;
}

/* rename_term — deep-copy a clause term into env->arena with fresh VarIds. */
static TermRef rename_term(TermRef ref, const TermArena *arena,
                            SolverEnv *env, RenameMap *rm,
                            const AtomTable *)
{
    for (uint32_t step = 0U; step < TERM_ARENA_CAPACITY; ++step) {
        const Term *t = term_get(arena, ref);
        if (t == nullptr) { return TERM_REF_INVALID; }

        switch (t->kind) {
            case TERM_KIND_ATOM:
                return term_make_atom(env->arena, t->data.atom_id);
            case TERM_KIND_INT:
                return term_make_int(env->arena, t->data.int_val);
            case TERM_KIND_VAR: {
                const VarId old   = t->data.var.var_id;
                VarId       fresh = rename_lookup(rm, old);
                if (fresh == VAR_ID_INVALID) {
                    const char *vname = t->data.var.name;
                    fresh = var_alloc(env->vars, vname[0] ? vname : "_");
                    if (fresh == VAR_ID_INVALID) { return TERM_REF_INVALID; }
                    if (rm->count < RENAME_MAP_CAP) {
                        rm->old_id[rm->count] = old;
                        rm->new_id[rm->count] = fresh;
                        rm->count++;
                    }
                }
                return term_make_var(env->arena, fresh, t->data.var.name);
            }
            case TERM_KIND_COMPOUND: {
                TermRef        new_args[TERM_MAX_ARITY];
                const uint8_t  arity = t->data.compound.arity;
                for (uint8_t i = 0U; i < arity; ++i) {
                    new_args[i] = rename_term(term_arg(arena, ref, i),
                                              arena, env, rm, nullptr);
                    if (new_args[i] == TERM_REF_INVALID) { return TERM_REF_INVALID; }
                }
                return term_make_compound(env->arena, t->data.compound.functor,
                                          arity, new_args);
            }
            default:
                return TERM_REF_INVALID;
        }
        break;
    }
    return TERM_REF_INVALID;
}

/* ---- GoalStack helpers ---------------------------------------------------- */

static int gs_push(GoalStack *gs, TermRef g)
{
    if (gs->top >= GOAL_STACK_CAPACITY) { return -1; }
    gs->goals[gs->top++] = g;
    return 0;
}

static TermRef gs_pop(GoalStack *gs)
{
    if (gs->top == 0U) { return TERM_REF_INVALID; }
    return gs->goals[--gs->top];
}

/* ---- Candidate helpers ---------------------------------------------------- */

/*
 * build_candidates — use the first-argument index (if available) to populate
 * cp->candidates[].  Returns false if there are no candidates at all.
 */
static bool build_candidates(ChoicePoint *cp, const PredEntry *pred,
                              SolverEnv *env, TermRef dgoal)
{
    TermRef first_arg = TERM_REF_INVALID;
    if (pred->arity >= 1U) {
        const Term *gt = term_get(env->arena, dgoal);
        if (gt != nullptr && gt->kind == TERM_KIND_COMPOUND) {
            first_arg = term_arg(env->arena, dgoal, 0U);
        }
    }

    cp->cand_count = db_index_range(pred, env->db, env->arena, env->vars,
                                    first_arg, cp->candidates, CP_MAX_CANDIDATES);
    cp->cand_idx   = 0U;
    return cp->cand_count > 0U;
}

/* ---- try_clause ----------------------------------------------------------- */

/*
 * Attempt to unify dgoal with clause at abs_pos and push body goals.
 * Returns true on success (bindings + body pushed).
 * On failure, undoes bindings down to mark and leaves stacks unchanged.
 */
static bool try_clause(uint32_t abs_pos, TermRef dgoal,
                       GoalStack *gs, SolverEnv *env)
{
    const StoredClause *sc = db_get_clause(env->db, abs_pos);
    if (sc == nullptr) { return false; }

    RenameMap rm;
    memset(&rm, 0, sizeof(RenameMap));
    const uint32_t mark = trail_mark(&env->trail);

    const TermRef fresh_head = rename_term(
        sc->head, env->clause_arena, env, &rm, env->atoms);
    if (fresh_head == TERM_REF_INVALID) { return false; }

    VLOG_SUBSYS("SOLVE", "trying clause at abs_pos=%u head_ref=%u", abs_pos, sc->head);

    if (!unify(dgoal, fresh_head, env->arena, env->vars, &env->trail)) {
        VLOG_SUBSYS("SOLVE", "%s", "unify failed");
        trail_undo(&env->trail, env->vars, mark);
        return false;
    }
    VLOG_SUBSYS("SOLVE", "unified ok, body_len=%u", sc->body_len);

    for (uint32_t bi = sc->body_len; bi > 0U; --bi) {
        const TermRef fresh_body = rename_term(
            sc->body[bi - 1U], env->clause_arena, env, &rm, env->atoms);
        if (fresh_body == TERM_REF_INVALID ||
            gs_push(gs, fresh_body) < 0) {
            trail_undo(&env->trail, env->vars, mark);
            return false;
        }
    }
    return true;
}

/* ---- Public API ----------------------------------------------------------- */

int solver_env_init(SolverEnv *env,
                    TermArena *arena, TermArena *clause_arena,
                    VarRegistry *vars, VarRegistry *clause_vars,
                    AtomTable *atoms, Database *db)
{
    if (!env || !arena || !clause_arena || !vars || !clause_vars || !atoms || !db) {
        return -1;
    }
    memset(env, 0, sizeof(SolverEnv));
    env->arena        = arena;
    env->clause_arena = clause_arena;
    env->vars         = vars;
    env->clause_vars  = clause_vars;
    env->atoms        = atoms;
    env->db           = db;
    trail_init(&env->trail);
    return 0;
}

uint32_t solve(SolverEnv *env, const TermRef *goals, uint32_t goal_count,
               SolutionCallback cb, void *userdata)
{
    if (!env || !goals || goal_count == 0U || !cb) { return 0U; }

    GoalStack   gs;
    ChoiceStack cs;
    memset(&gs, 0, sizeof(GoalStack));
    memset(&cs, 0, sizeof(ChoiceStack));

    uint32_t solutions = 0U;

    for (uint32_t gi = goal_count; gi > 0U; --gi) {
        if (gs_push(&gs, goals[gi - 1U]) < 0) { return 0U; }
    }

    bool do_backtrack = false;

    for (uint32_t iter = 0U; iter < 10000000U; ++iter) {

        if (do_backtrack) {
            do_backtrack = false;
            goto backtrack;
        }

        /* SUCCESS */
        if (gs.top == 0U) {
            solutions++;
            if (cb(env, goals, goal_count, userdata) == SOLVE_STOP) {
                return solutions;
            }
            if (cs.top == 0U) { return solutions; }
            goto backtrack;
        }

        /* pop and process next goal */
        {
            const TermRef  goal    = gs_pop(&gs);
            const TermRef  dgoal   = deref(goal, env->arena, env->vars);
            const Term    *gt      = term_get(env->arena, dgoal);
            AtomId         functor = ATOM_ID_INVALID;
            uint8_t        arity   = 0U;

            if (gt == nullptr)                  { goto backtrack; }
            if (gt->kind == TERM_KIND_ATOM)     { functor = gt->data.atom_id; arity = 0U; }
            else if (gt->kind == TERM_KIND_COMPOUND) {
                functor = gt->data.compound.functor;
                arity   = gt->data.compound.arity;
            } else { goto backtrack; }

            /* built-in? */
            {
                BuiltinFn bf = builtin_lookup(functor, arity, env->atoms);
                if (bf != nullptr) {
                    switch (bf(dgoal, env)) {
                        case BUILTIN_SUCCEED: continue;
                        case BUILTIN_FAIL:    goto backtrack;
                        case BUILTIN_CUT:     cs.top = 0U; continue;
                        case BUILTIN_ERROR:   return solutions;
                    }
                }
            }

            /* user-defined clause lookup */
            {
                const PredEntry *pred = db_get_pred(env->db, functor, arity);
                VLOG_SUBSYS("SOLVE", "goal functor=%u arity=%u pred=%s count=%u",
                            functor, arity,
                            pred ? atom_spelling(env->atoms, functor) : "?NONE",
                            pred ? pred->count : 0U);
                if (pred == nullptr || pred->count == 0U) {
                    VLOG_SUBSYS("SOLVE", "%s", "no clauses -> backtrack");
                    goto backtrack;
                }

                /* Build candidate list using first-argument index */
                if (cs.top >= CHOICE_STACK_CAPACITY) { goto backtrack; }
                ChoicePoint *cp = &cs.items[cs.top];

                cp->goal       = goal;
                cp->trail_mark = trail_mark(&env->trail);
                cp->goal_top   = gs.top;

                if (!build_candidates(cp, pred, env, dgoal)) {
                    goto backtrack;
                }

                /* Try first candidate immediately; push choice point only if
                 * more candidates remain. */
                const uint32_t first_pos = cp->candidates[0];
                cp->cand_idx = 1U;

                if (cp->cand_count > 1U) {
                    cs.top++;  /* push choice point for remaining candidates */
                }

                if (!try_clause(first_pos, dgoal, &gs, env)) {
                    if (cp->cand_count > 1U) {
                        /* choice point was pushed — backtrack into it */
                        goto backtrack;
                    }
                    goto backtrack;
                }
            }
            continue;
        }

        backtrack:
        {
            if (cs.top == 0U) { return solutions; }

            ChoicePoint *cp = &cs.items[cs.top - 1U];
            trail_undo(&env->trail, env->vars, cp->trail_mark);
            gs.top = cp->goal_top;

            /* Advance through remaining candidates */
            while (cp->cand_idx < cp->cand_count) {
                const uint32_t pos = cp->candidates[cp->cand_idx++];
                const TermRef dgoal = deref(cp->goal, env->arena, env->vars);

                if (cp->cand_idx >= cp->cand_count) { cs.top--; }

                if (try_clause(pos, dgoal, &gs, env)) {
                    goto next_iter;
                }

                /* try_clause undid its own bindings; undo trail to choice mark */
                trail_undo(&env->trail, env->vars, cp->trail_mark);
                gs.top = cp->goal_top;

                /* If we just popped the cp (cand_idx hit end), we need
                 * to continue up the choice stack. */
                if (cp->cand_idx >= cp->cand_count) { goto backtrack; }
            }

            /* Exhausted candidates */
            cs.top--;
            goto backtrack;

            next_iter:;
        }
        continue;
    }
    return solutions;
}

/*
 * stats.hpp — Query statistics collector for Epilog 0.2.
 *
 * Tracks how many times each (functor, arity) query is executed and how many
 * solutions it produces.  Used as groundwork for Phase 0.6 (predictive
 * execution).
 *
 * JPL rules: no post-init malloc, bounded capacity, no recursion.
 */

#pragma once

#include <cstdint>
#include "atoms.hpp"

constexpr uint32_t STATS_MAX_ENTRIES = 512U;

struct QueryStat {
    AtomId   functor    = ATOM_ID_INVALID;
    uint8_t  arity      = 0U;
    uint64_t call_count = 0ULL;  /* times this query was started */
    uint64_t soln_count = 0ULL;  /* total solutions produced */
};

struct QueryStats {
    QueryStat entries[STATS_MAX_ENTRIES];
    uint32_t  count = 0U;
};

/* stats_init — zero-initialise *s. */
int stats_init(QueryStats *s);

/*
 * stats_record_call — increment call_count for (functor, arity).
 * Creates a new entry if none exists.  Returns 0 or -1 on overflow.
 */
int stats_record_call(QueryStats *s, AtomId functor, uint8_t arity);

/*
 * stats_record_solutions — add n to soln_count for (functor, arity).
 * Entry must already exist (call stats_record_call first).
 */
int stats_record_solutions(QueryStats *s, AtomId functor, uint8_t arity,
                            uint64_t n);

/* stats_get — return pointer to the entry or nullptr if absent. */
const QueryStat *stats_get(const QueryStats *s, AtomId functor, uint8_t arity);

/* stats_top_n — fill out[0..n) with the n most-called entries (descending).
 * Returns how many were written. */
uint32_t stats_top_n(const QueryStats *s, QueryStat *out, uint32_t n);

/* stats_reset — zero all counters but keep entries. */
void stats_reset(QueryStats *s);

/*
 * stats.cpp — Query statistics collector implementation.
 * JPL rules: no recursion, bounded loops, no post-init malloc.
 */

#include "../include/stats.hpp"
#include <cstring>

static QueryStat *find_entry(QueryStats *s, AtomId functor, uint8_t arity)
{
    for (uint32_t i = 0U; i < s->count; ++i) {
        if (s->entries[i].functor == functor && s->entries[i].arity == arity) {
            return &s->entries[i];
        }
    }
    return nullptr;
}

int stats_init(QueryStats *s)
{
    if (s == nullptr) { return -1; }
    memset(s, 0, sizeof(QueryStats));
    return 0;
}

int stats_record_call(QueryStats *s, AtomId functor, uint8_t arity)
{
    if (s == nullptr || functor == ATOM_ID_INVALID) { return -1; }
    QueryStat *e = find_entry(s, functor, arity);
    if (e == nullptr) {
        if (s->count >= STATS_MAX_ENTRIES) { return -1; }
        e = &s->entries[s->count++];
        memset(e, 0, sizeof(QueryStat));
        e->functor = functor;
        e->arity   = arity;
    }
    e->call_count++;
    return 0;
}

int stats_record_solutions(QueryStats *s, AtomId functor, uint8_t arity,
                            uint64_t n)
{
    if (s == nullptr || functor == ATOM_ID_INVALID) { return -1; }
    QueryStat *e = find_entry(s, functor, arity);
    if (e == nullptr) { return -1; }
    e->soln_count += n;
    return 0;
}

const QueryStat *stats_get(const QueryStats *s, AtomId functor, uint8_t arity)
{
    if (s == nullptr || functor == ATOM_ID_INVALID) { return nullptr; }
    for (uint32_t i = 0U; i < s->count; ++i) {
        if (s->entries[i].functor == functor && s->entries[i].arity == arity) {
            return &s->entries[i];
        }
    }
    return nullptr;
}

uint32_t stats_top_n(const QueryStats *s, QueryStat *out, uint32_t n)
{
    if (s == nullptr || out == nullptr || n == 0U) { return 0U; }

    /* Simple selection: copy all entries into out[], then partial insertion sort
     * to bring the top-n to the front.  O(count * n) — acceptable for small n. */
    uint32_t total = (s->count < n) ? s->count : n;

    /* Copy up to n entries, maintaining descending call_count order */
    uint32_t written = 0U;
    for (uint32_t i = 0U; i < s->count && written < n; ++i) {
        /* Insert s->entries[i] into out[0..written) in sorted position */
        const QueryStat *src = &s->entries[i];
        if (written < n) {
            /* Find insertion point */
            uint32_t pos = written;
            for (uint32_t j = 0U; j < written; ++j) {
                if (src->call_count > out[j].call_count) { pos = j; break; }
            }
            /* Shift right */
            for (uint32_t k = (written < n ? written : n - 1U); k > pos; --k) {
                out[k] = out[k - 1U];
            }
            out[pos] = *src;
            written++;
        }
    }
    (void)total;
    return written;
}

void stats_reset(QueryStats *s)
{
    if (s == nullptr) { return; }
    for (uint32_t i = 0U; i < s->count; ++i) {
        s->entries[i].call_count = 0ULL;
        s->entries[i].soln_count = 0ULL;
    }
}

/*
 * memo.hpp — Memoization (tabling) cache for pure subgoals, Epilog 0.2.
 *
 * Caches the complete solution set for ground queries against user-defined
 * predicates.  Only ground queries (no unbound variables in the goal) are
 * eligible for caching.
 *
 * Invariant: the cache must be invalidated whenever assert or retract modifies
 * the database, since a cached result may no longer be correct.
 *
 * JPL rules: no post-init malloc, bounded capacity, no recursion.
 */

#pragma once

#include <cstdint>
#include "atoms.hpp"
#include "terms.hpp"

/* Maximum number of distinct queries we cache */
constexpr uint32_t MEMO_MAX_ENTRIES   = 256U;
/* Maximum solutions stored per cached query */
constexpr uint32_t MEMO_MAX_SOLUTIONS = 64U;
/* Maximum argument slots across all cached solutions (flat pool) */
constexpr uint32_t MEMO_ARG_POOL      = 4096U;

/*
 * A MemoKey identifies a ground query: functor + arity + ground argument
 * values (atoms and integers only — compound terms are not cached).
 */
constexpr uint8_t MEMO_MAX_ARITY = 8U;

enum MemoArgKind : uint8_t {
    MEMO_ARG_ATOM = 0,
    MEMO_ARG_INT  = 1
};

union MemoArgVal {
    AtomId  atom_id;
    int32_t int_val;
};

struct MemoKey {
    AtomId      functor                 = ATOM_ID_INVALID;
    uint8_t     arity                   = 0U;
    MemoArgKind arg_kind[MEMO_MAX_ARITY] = {};
    MemoArgVal  arg_val [MEMO_MAX_ARITY] = {};
};

/*
 * A MemoSolution is one solution binding, stored as a flat list of
 * (kind, value) pairs in the shared arg pool.
 */
struct MemoSolution {
    uint32_t arg_start = 0U;  /* index into MemoCache::arg_pool */
    uint8_t  arg_count = 0U;
};

struct MemoEntry {
    MemoKey      key         = {};
    MemoSolution solutions[MEMO_MAX_SOLUTIONS] = {};
    uint32_t     soln_count  = 0U;
    bool         complete    = false;  /* true = all solutions stored */
    bool         valid       = false;  /* false = entry is free/invalidated */
};

struct MemoArgSlot {
    MemoArgKind kind = MEMO_ARG_ATOM;
    MemoArgVal  val  = {};
};

struct MemoCache {
    MemoEntry   entries[MEMO_MAX_ENTRIES] = {};
    uint32_t    entry_count               = 0U;
    MemoArgSlot arg_pool[MEMO_ARG_POOL]   = {};
    uint32_t    arg_pool_count            = 0U;
    uint64_t    hits                      = 0ULL;
    uint64_t    misses                    = 0ULL;
};

/* memo_init — zero-initialise *c. */
int memo_init(MemoCache *c);

/*
 * memo_key_from_goal — extract a MemoKey from a fully-ground query term.
 * Returns false if the term has variables or compound arguments (not cacheable).
 */
bool memo_key_from_goal(MemoKey *key, TermRef goal_ref,
                        const TermArena *arena, const VarRegistry *vars);

/* memo_lookup — find a complete entry for key.  Returns nullptr on miss. */
const MemoEntry *memo_lookup(MemoCache *c, const MemoKey *key);

/*
 * memo_begin — find or create an incomplete entry for key.
 * Returns nullptr on capacity overflow.
 */
MemoEntry *memo_begin(MemoCache *c, const MemoKey *key);

/*
 * memo_add_solution — append a solution to an in-progress entry.
 * sol_args[0..arity) are the bound values for the query variables.
 * Returns 0 or -1 on overflow (entry remains usable, just truncated).
 */
int memo_add_solution(MemoCache *c, MemoEntry *entry,
                      const MemoArgSlot *sol_args, uint8_t arity);

/* memo_complete — mark an entry as fully populated. */
void memo_complete(MemoEntry *entry);

/* memo_invalidate — mark all entries invalid (call on assert/retract). */
void memo_invalidate(MemoCache *c);

/*
 * memo.cpp — Memoization (tabling) cache implementation.
 * JPL rules: no recursion, bounded loops, no post-init malloc.
 */

#include "../include/memo.hpp"
#include "../include/variables.hpp"
#include <cstring>

static bool keys_equal(const MemoKey *a, const MemoKey *b)
{
    if (a->functor != b->functor || a->arity != b->arity) { return false; }
    for (uint8_t i = 0U; i < a->arity; ++i) {
        if (a->arg_kind[i] != b->arg_kind[i]) { return false; }
        if (a->arg_kind[i] == MEMO_ARG_ATOM) {
            if (a->arg_val[i].atom_id != b->arg_val[i].atom_id) { return false; }
        } else {
            if (a->arg_val[i].int_val != b->arg_val[i].int_val) { return false; }
        }
    }
    return true;
}

int memo_init(MemoCache *c)
{
    if (c == nullptr) { return -1; }
    memset(c, 0, sizeof(MemoCache));
    return 0;
}

bool memo_key_from_goal(MemoKey *key, TermRef goal_ref,
                        const TermArena *arena, const VarRegistry *vars)
{
    if (key == nullptr || arena == nullptr) { return false; }

    const Term *gt = term_get(arena, goal_ref);
    if (gt == nullptr) { return false; }

    AtomId  functor = ATOM_ID_INVALID;
    uint8_t arity   = 0U;

    if (gt->kind == TERM_KIND_ATOM) {
        functor = gt->data.atom_id;
        arity   = 0U;
    } else if (gt->kind == TERM_KIND_COMPOUND) {
        functor = gt->data.compound.functor;
        arity   = gt->data.compound.arity;
    } else {
        return false;
    }

    if (arity > MEMO_MAX_ARITY) { return false; }

    memset(key, 0, sizeof(MemoKey));
    key->functor = functor;
    key->arity   = arity;

    for (uint8_t i = 0U; i < arity; ++i) {
        TermRef arg_ref = term_arg(arena, goal_ref, i);

        /* Dereference variable bindings */
        for (uint32_t step = 0U; step < VAR_REGISTRY_CAPACITY; ++step) {
            const Term *t = term_get(arena, arg_ref);
            if (t == nullptr) { return false; }
            if (t->kind != TERM_KIND_VAR) { break; }
            if (vars == nullptr) { return false; }
            WalkResult wr = var_walk(vars, t->data.var.var_id);
            if (wr.tag == TERM_UNBOUND) { return false; }  /* variable — not ground */
            if (wr.tag == TERM_TERMREF) { arg_ref = wr.value.term_ref; }
            else { return false; }
        }

        const Term *at = term_get(arena, arg_ref);
        if (at == nullptr) { return false; }
        if (at->kind == TERM_KIND_ATOM) {
            key->arg_kind[i]         = MEMO_ARG_ATOM;
            key->arg_val[i].atom_id  = at->data.atom_id;
        } else if (at->kind == TERM_KIND_INT) {
            key->arg_kind[i]         = MEMO_ARG_INT;
            key->arg_val[i].int_val  = at->data.int_val;
        } else {
            return false;  /* compound arg — skip caching */
        }
    }
    return true;
}

const MemoEntry *memo_lookup(MemoCache *c, const MemoKey *key)
{
    if (c == nullptr || key == nullptr) { return nullptr; }
    for (uint32_t i = 0U; i < c->entry_count; ++i) {
        MemoEntry *e = &c->entries[i];
        if (!e->valid || !e->complete) { continue; }
        if (keys_equal(&e->key, key)) {
            c->hits++;
            return e;
        }
    }
    c->misses++;
    return nullptr;
}

MemoEntry *memo_begin(MemoCache *c, const MemoKey *key)
{
    if (c == nullptr || key == nullptr) { return nullptr; }

    /* Reuse an invalid slot if available */
    for (uint32_t i = 0U; i < c->entry_count; ++i) {
        if (!c->entries[i].valid) {
            MemoEntry *e = &c->entries[i];
            memset(e, 0, sizeof(MemoEntry));
            e->key   = *key;
            e->valid = true;
            return e;
        }
    }

    if (c->entry_count >= MEMO_MAX_ENTRIES) { return nullptr; }
    MemoEntry *e = &c->entries[c->entry_count++];
    memset(e, 0, sizeof(MemoEntry));
    e->key   = *key;
    e->valid = true;
    return e;
}

int memo_add_solution(MemoCache *c, MemoEntry *entry,
                      const MemoArgSlot *sol_args, uint8_t arity)
{
    if (c == nullptr || entry == nullptr) { return -1; }
    if (entry->soln_count >= MEMO_MAX_SOLUTIONS) { return -1; }
    if (c->arg_pool_count + arity > MEMO_ARG_POOL) { return -1; }

    MemoSolution *s = &entry->solutions[entry->soln_count];
    s->arg_start = c->arg_pool_count;
    s->arg_count = arity;

    for (uint8_t i = 0U; i < arity; ++i) {
        c->arg_pool[c->arg_pool_count++] = sol_args[i];
    }
    entry->soln_count++;
    return 0;
}

void memo_complete(MemoEntry *entry)
{
    if (entry != nullptr) { entry->complete = true; }
}

void memo_invalidate(MemoCache *c)
{
    if (c == nullptr) { return; }
    for (uint32_t i = 0U; i < c->entry_count; ++i) {
        c->entries[i].valid    = false;
        c->entries[i].complete = false;
    }
    c->entry_count    = 0U;
    c->arg_pool_count = 0U;
}

/*
 * test_indexing.cpp — Tests for the first-argument index (Phase 0.2).
 *
 * Verifies that:
 *   - db_build_index correctly classifies ground vs. variable first-arg clauses
 *   - db_index_range returns the right subset for ground queries
 *   - db_index_range falls back to all clauses for variable queries
 *   - The solver produces correct results with indexing enabled
 *   - Indexing is automatically rebuilt after assert
 */

#include "test_framework.hpp"
#include "../include/database.hpp"
#include "../include/solver.hpp"
#include "../include/parser.hpp"
#include "../include/lexer.hpp"
#include <cstring>

/* ---- Shared test harness (same pattern as test_solver.cpp) --------------- */

struct IdxCtx {
    AtomTable   atoms;
    Database    db;
    TermArena   clause_arena;
    VarRegistry clause_vars;
    TermArena   query_arena;
    VarRegistry query_vars;

    IdxCtx() {
        atom_table_init(&atoms);
        db_init(&db);
        term_arena_init(&clause_arena);
        var_registry_init(&clause_vars);
        term_arena_init(&query_arena);
        var_registry_init(&query_vars);
    }

    int load(const char *src) {
        static TokenList toks;
        memset(&toks, 0, sizeof(toks));
        if (lex(src, &toks) < 0) { return -1; }
        var_registry_init(&clause_vars);
        Parser p;
        if (parser_init(&p, &toks, &clause_arena, &atoms, &clause_vars) < 0) { return -1; }
        int n = 0;
        ParsedClause c;
        for (;;) {
            memset(&c, 0, sizeof(c));
            ParseResult r = parser_next_clause(&p, &c);
            if (r == PARSE_EOF) break;
            if (r != PARSE_OK)  return -1;
            if (db_assert_last(&db, &c, &clause_arena) < 0) return -1;
            n++;
        }
        return n;
    }

    uint32_t query(const char *src) {
        static TokenList toks;
        memset(&toks, 0, sizeof(toks));
        term_arena_init(&query_arena);
        var_registry_init(&query_vars);
        if (lex(src, &toks) < 0) { return 0; }
        Parser p;
        if (parser_init(&p, &toks, &query_arena, &atoms, &query_vars) < 0) return 0;
        ParsedQuery pq;
        if (parser_query(&p, &pq) != PARSE_OK) return 0;
        SolverEnv env;
        solver_env_init(&env, &query_arena, &clause_arena,
                        &query_vars, &clause_vars, &atoms, &db);
        return solve(&env, pq.goals, pq.goal_count,
                     [](SolverEnv *, const TermRef *, uint32_t, void *) {
                         return SOLVE_NEXT;
                     }, nullptr);
    }
};

/* ---- Unit tests for db_build_index / db_index_range ---------------------- */

TEST("index: ground atom first-arg creates one bucket per distinct value")
{
    IdxCtx ctx;
    REQUIRE(ctx.load("color(red). color(green). color(blue).") == 3);

    AtomId functor = atom_lookup(&ctx.atoms, "color");
    REQUIRE(functor != ATOM_ID_INVALID);

    const PredEntry *pred = db_get_pred(&ctx.db, functor, 1U);
    REQUIRE(pred != nullptr);
    EXPECT(pred->index.built);
    EXPECT_EQ(pred->index.idx_bucket_count, 3U);
    EXPECT_EQ(pred->index.idx_var_count, 0U);
}

TEST("index: variable first-arg clause goes to var catch-all bucket")
{
    IdxCtx ctx;
    REQUIRE(ctx.load("f(X) :- true. f(a). f(b).") == 3);

    AtomId functor = atom_lookup(&ctx.atoms, "f");
    REQUIRE(functor != ATOM_ID_INVALID);

    const PredEntry *pred = db_get_pred(&ctx.db, functor, 1U);
    REQUIRE(pred != nullptr);
    EXPECT(pred->index.built);
    /* f(X) is var-first-arg; f(a) and f(b) are ground */
    EXPECT_EQ(pred->index.idx_var_count, 1U);
    EXPECT_EQ(pred->index.idx_bucket_count, 2U);
}

TEST("index: db_index_range with ground atom returns only matching clauses + var clauses")
{
    IdxCtx ctx;
    REQUIRE(ctx.load("f(X) :- true. f(a). f(b). f(c).") == 4);

    AtomId functor = atom_lookup(&ctx.atoms, "f");
    AtomId a_id    = atom_intern(&ctx.atoms, "a");
    REQUIRE(functor != ATOM_ID_INVALID);
    REQUIRE(a_id != ATOM_ID_INVALID);

    const PredEntry *pred = db_get_pred(&ctx.db, functor, 1U);
    REQUIRE(pred != nullptr);

    /* Build a ground atom term for 'a' in query arena */
    TermRef arg = term_make_atom(&ctx.query_arena, a_id);
    TermRef goal_args[1] = { arg };
    AtomId f_id = functor;
    TermRef goal = term_make_compound(&ctx.query_arena, f_id, 1U, goal_args);

    TermRef first_arg = term_arg(&ctx.query_arena, goal, 0U);

    uint32_t out[16];
    uint32_t n = db_index_range(pred, &ctx.db, &ctx.query_arena, &ctx.query_vars,
                                first_arg, out, 16U);

    /* Should return: f(X) (var clause) + f(a) (matching ground clause) = 2 */
    EXPECT_EQ(n, 2U);
}

TEST("index: db_index_range for unknown atom returns only var clauses")
{
    IdxCtx ctx;
    REQUIRE(ctx.load("f(X) :- true. f(a). f(b).") == 3);

    AtomId functor = atom_lookup(&ctx.atoms, "f");
    AtomId z_id    = atom_intern(&ctx.atoms, "z");
    REQUIRE(functor != ATOM_ID_INVALID);

    const PredEntry *pred = db_get_pred(&ctx.db, functor, 1U);
    REQUIRE(pred != nullptr);

    TermRef arg = term_make_atom(&ctx.query_arena, z_id);
    TermRef goal_args[1] = { arg };
    TermRef goal = term_make_compound(&ctx.query_arena, functor, 1U, goal_args);
    TermRef first_arg = term_arg(&ctx.query_arena, goal, 0U);

    uint32_t out[16];
    uint32_t n = db_index_range(pred, &ctx.db, &ctx.query_arena, &ctx.query_vars,
                                first_arg, out, 16U);

    /* Only f(X) matches (via var catch-all); f(a) and f(b) are skipped */
    EXPECT_EQ(n, 1U);
}

TEST("index: arity-0 predicates return all clauses (no indexing)")
{
    IdxCtx ctx;
    REQUIRE(ctx.load("fact. fact. fact.") == 3);

    AtomId functor = atom_lookup(&ctx.atoms, "fact");
    REQUIRE(functor != ATOM_ID_INVALID);

    const PredEntry *pred = db_get_pred(&ctx.db, functor, 0U);
    REQUIRE(pred != nullptr);

    uint32_t out[16];
    uint32_t n = db_index_range(pred, &ctx.db, &ctx.query_arena, &ctx.query_vars,
                                TERM_REF_INVALID, out, 16U);
    EXPECT_EQ(n, 3U);
}

/* ---- Solver integration with indexing ------------------------------------ */

TEST("indexing: ground atom query finds correct single solution")
{
    IdxCtx ctx;
    ctx.load("color(red). color(green). color(blue).");
    EXPECT_EQ(ctx.query("?- color(red)."),   1U);
    EXPECT_EQ(ctx.query("?- color(green)."), 1U);
    EXPECT_EQ(ctx.query("?- color(blue)."),  1U);
}

TEST("indexing: ground atom query for absent value fails")
{
    IdxCtx ctx;
    ctx.load("color(red). color(green). color(blue).");
    EXPECT_EQ(ctx.query("?- color(yellow)."), 0U);
}

TEST("indexing: variable query still returns all solutions")
{
    IdxCtx ctx;
    ctx.load("color(red). color(green). color(blue).");
    EXPECT_EQ(ctx.query("?- color(X)."), 3U);
}

TEST("indexing: mixed var/ground clauses resolve correctly")
{
    IdxCtx ctx;
    /* f(X) :- true means f(_) always succeeds; f(a) adds a second solution for a */
    ctx.load("f(X) :- true. f(a).");
    EXPECT_EQ(ctx.query("?- f(a)."), 2U);   /* f(X) + f(a) */
    EXPECT_EQ(ctx.query("?- f(b)."), 1U);   /* only f(X) */
}

TEST("indexing: large fact base — only matching clause tried for ground query")
{
    IdxCtx ctx;
    /* Load 10 distinct ground facts; ground query should find exactly one */
    ctx.load(
        "item(a). item(b). item(c). item(d). item(e). "
        "item(f). item(g). item(h). item(i). item(j)."
    );
    EXPECT_EQ(ctx.query("?- item(e)."), 1U);
    EXPECT_EQ(ctx.query("?- item(z)."), 0U);
    EXPECT_EQ(ctx.query("?- item(X)."), 10U);
}

TEST("indexing: index rebuilt automatically after assert")
{
    IdxCtx ctx;
    ctx.load("item(a). item(b).");
    EXPECT_EQ(ctx.query("?- item(c)."), 0U);
    ctx.load("item(c).");
    EXPECT_EQ(ctx.query("?- item(c)."), 1U);
}

TEST("indexing: 0.1 acceptance still passes with indexing enabled")
{
    IdxCtx ctx;
    REQUIRE(ctx.load(
        "parent(alice, bob). "
        "parent(bob, carol). "
        "grandparent(X, Y) :- parent(X, Z), parent(Z, Y)."
    ) == 3);
    EXPECT_EQ(ctx.query("?- grandparent(alice, carol)."), 1U);
    EXPECT_EQ(ctx.query("?- grandparent(alice, alice)."), 0U);
}

TEST("indexing: integer first-arg is indexed separately from atoms")
{
    IdxCtx ctx;
    ctx.load("val(1). val(2). val(3).");
    EXPECT_EQ(ctx.query("?- val(1)."), 1U);
    EXPECT_EQ(ctx.query("?- val(4)."), 0U);
    EXPECT_EQ(ctx.query("?- val(X)."), 3U);
}

