/*
 * test_stats.cpp — Tests for the query statistics collector (Phase 0.2).
 */

#include "test_framework.hpp"
#include "../include/stats.hpp"
#include "../include/atoms.hpp"
#include <cstring>

static AtomTable g_atoms;
static bool      g_atoms_init = false;

static AtomTable *atoms()
{
    if (!g_atoms_init) {
        atom_table_init(&g_atoms);
        g_atoms_init = true;
    }
    return &g_atoms;
}

TEST("stats: init zeroes all fields")
{
    QueryStats s;
    EXPECT_EQ(stats_init(&s), 0);
    EXPECT_EQ(s.count, 0U);
}

TEST("stats: record_call creates a new entry")
{
    QueryStats s;
    stats_init(&s);
    AtomId id = atom_intern(atoms(), "foo");
    REQUIRE(id != ATOM_ID_INVALID);

    EXPECT_EQ(stats_record_call(&s, id, 2U), 0);
    EXPECT_EQ(s.count, 1U);

    const QueryStat *e = stats_get(&s, id, 2U);
    REQUIRE(e != nullptr);
    EXPECT_EQ(e->call_count, 1ULL);
    EXPECT_EQ(e->soln_count, 0ULL);
}

TEST("stats: record_call increments existing entry")
{
    QueryStats s;
    stats_init(&s);
    AtomId id = atom_intern(atoms(), "bar");
    REQUIRE(id != ATOM_ID_INVALID);

    stats_record_call(&s, id, 1U);
    stats_record_call(&s, id, 1U);
    stats_record_call(&s, id, 1U);

    const QueryStat *e = stats_get(&s, id, 1U);
    REQUIRE(e != nullptr);
    EXPECT_EQ(e->call_count, 3ULL);
}

TEST("stats: different arity is a different entry")
{
    QueryStats s;
    stats_init(&s);
    AtomId id = atom_intern(atoms(), "baz");
    REQUIRE(id != ATOM_ID_INVALID);

    stats_record_call(&s, id, 1U);
    stats_record_call(&s, id, 2U);

    EXPECT_EQ(s.count, 2U);
    const QueryStat *e1 = stats_get(&s, id, 1U);
    const QueryStat *e2 = stats_get(&s, id, 2U);
    REQUIRE(e1 != nullptr);
    REQUIRE(e2 != nullptr);
    EXPECT_EQ(e1->call_count, 1ULL);
    EXPECT_EQ(e2->call_count, 1ULL);
}

TEST("stats: record_solutions accumulates")
{
    QueryStats s;
    stats_init(&s);
    AtomId id = atom_intern(atoms(), "qux");
    REQUIRE(id != ATOM_ID_INVALID);

    stats_record_call(&s, id, 0U);
    stats_record_solutions(&s, id, 0U, 3ULL);
    stats_record_solutions(&s, id, 0U, 7ULL);

    const QueryStat *e = stats_get(&s, id, 0U);
    REQUIRE(e != nullptr);
    EXPECT_EQ(e->soln_count, 10ULL);
}

TEST("stats: get returns nullptr for absent entry")
{
    QueryStats s;
    stats_init(&s);
    AtomId id = atom_intern(atoms(), "missing");
    REQUIRE(id != ATOM_ID_INVALID);
    EXPECT_NULL(stats_get(&s, id, 0U));
}

TEST("stats: reset clears counters but keeps entries")
{
    QueryStats s;
    stats_init(&s);
    AtomId id = atom_intern(atoms(), "rst");
    REQUIRE(id != ATOM_ID_INVALID);

    stats_record_call(&s, id, 0U);
    stats_record_solutions(&s, id, 0U, 5ULL);
    stats_reset(&s);

    EXPECT_EQ(s.count, 1U);  /* entry still there */
    const QueryStat *e = stats_get(&s, id, 0U);
    REQUIRE(e != nullptr);
    EXPECT_EQ(e->call_count, 0ULL);
    EXPECT_EQ(e->soln_count, 0ULL);
}

TEST("stats: top_n returns entries in descending call_count order")
{
    QueryStats s;
    stats_init(&s);

    AtomId a = atom_intern(atoms(), "top_a");
    AtomId b = atom_intern(atoms(), "top_b");
    AtomId c = atom_intern(atoms(), "top_c");
    REQUIRE(a != ATOM_ID_INVALID);
    REQUIRE(b != ATOM_ID_INVALID);
    REQUIRE(c != ATOM_ID_INVALID);

    stats_record_call(&s, a, 0U);                        /* call_count = 1 */
    stats_record_call(&s, b, 0U);
    stats_record_call(&s, b, 0U);
    stats_record_call(&s, b, 0U);                        /* call_count = 3 */
    stats_record_call(&s, c, 0U);
    stats_record_call(&s, c, 0U);                        /* call_count = 2 */

    QueryStat top[3];
    uint32_t n = stats_top_n(&s, top, 3U);
    EXPECT_EQ(n, 3U);
    /* First entry should be b (call_count 3) */
    EXPECT_EQ(top[0].functor, b);
    EXPECT_EQ(top[0].call_count, 3ULL);
}

TEST("stats: null guard — init returns -1 for null")
{
    EXPECT_EQ(stats_init(nullptr), -1);
}

TEST("stats: record_call fails for ATOM_ID_INVALID")
{
    QueryStats s;
    stats_init(&s);
    EXPECT_EQ(stats_record_call(&s, ATOM_ID_INVALID, 0U), -1);
}

