/*
 * test_memo.cpp — Tests for the memoization (tabling) cache (Phase 0.2).
 */

#include "test_framework.hpp"
#include "../include/memo.hpp"
#include "../include/atoms.hpp"
#include "../include/terms.hpp"
#include "../include/variables.hpp"
#include <cstring>

static AtomTable   g_atoms;
static TermArena   g_arena;
static VarRegistry g_vars;
static bool        g_init = false;

static void ensure_init()
{
    if (!g_init) {
        atom_table_init(&g_atoms);
        term_arena_init(&g_arena);
        var_registry_init(&g_vars);
        g_init = true;
    }
}

/* Build a ground compound term in g_arena */
static TermRef make_goal(const char *functor_name, const AtomId *arg_atoms,
                         uint8_t arity)
{
    ensure_init();
    AtomId fid = atom_intern(&g_atoms, functor_name);
    if (arity == 0U) { return term_make_atom(&g_arena, fid); }
    TermRef args[MEMO_MAX_ARITY];
    for (uint8_t i = 0U; i < arity; ++i) {
        args[i] = term_make_atom(&g_arena, arg_atoms[i]);
    }
    return term_make_compound(&g_arena, fid, arity, args);
}

/* ---- Tests ---------------------------------------------------------------- */

TEST("memo: init zeroes cache")
{
    MemoCache c;
    EXPECT_EQ(memo_init(&c), 0);
    EXPECT_EQ(c.entry_count,    0U);
    EXPECT_EQ(c.arg_pool_count, 0U);
    EXPECT_EQ(c.hits,           0ULL);
    EXPECT_EQ(c.misses,         0ULL);
}

TEST("memo: key_from_goal extracts ground atom-0 goal")
{
    ensure_init();
    AtomId aid = atom_intern(&g_atoms, "true");
    TermRef goal = term_make_atom(&g_arena, aid);

    MemoKey key;
    bool ok = memo_key_from_goal(&key, goal, &g_arena, &g_vars);
    EXPECT(ok);
    EXPECT_EQ(key.functor, aid);
    EXPECT_EQ(key.arity,   0U);
}

TEST("memo: key_from_goal extracts ground compound goal")
{
    ensure_init();
    AtomId arg = atom_intern(&g_atoms, "alice");
    TermRef goal = make_goal("likes", &arg, 1U);

    MemoKey key;
    bool ok = memo_key_from_goal(&key, goal, &g_arena, &g_vars);
    EXPECT(ok);
    EXPECT_EQ(key.arity, 1U);
    EXPECT_EQ(key.arg_kind[0], MEMO_ARG_ATOM);
    EXPECT_EQ(key.arg_val[0].atom_id, arg);
}

TEST("memo: key_from_goal fails for unbound variable argument")
{
    ensure_init();
    /* Build f(X) where X is unbound */
    VarId xid = var_alloc(&g_vars, "X");
    REQUIRE(xid != VAR_ID_INVALID);
    TermRef xref = term_make_var(&g_arena, xid, "X");
    AtomId fid = atom_intern(&g_atoms, "f_var");
    TermRef goal = term_make_compound(&g_arena, fid, 1U, &xref);

    MemoKey key;
    bool ok = memo_key_from_goal(&key, goal, &g_arena, &g_vars);
    EXPECT(!ok);
}

TEST("memo: begin creates a new entry")
{
    MemoCache c;
    memo_init(&c);

    ensure_init();
    AtomId aid = atom_intern(&g_atoms, "cached_pred");
    TermRef goal = term_make_atom(&g_arena, aid);

    MemoKey key;
    REQUIRE(memo_key_from_goal(&key, goal, &g_arena, &g_vars));

    MemoEntry *e = memo_begin(&c, &key);
    REQUIRE(e != nullptr);
    EXPECT(e->valid);
    EXPECT(!e->complete);
    EXPECT_EQ(e->soln_count, 0U);
    EXPECT_EQ(c.entry_count, 1U);
}

TEST("memo: lookup returns nullptr before complete")
{
    MemoCache c;
    memo_init(&c);

    ensure_init();
    AtomId aid = atom_intern(&g_atoms, "incomplete");
    TermRef goal = term_make_atom(&g_arena, aid);

    MemoKey key;
    REQUIRE(memo_key_from_goal(&key, goal, &g_arena, &g_vars));

    memo_begin(&c, &key);  /* incomplete */
    EXPECT_NULL(memo_lookup(&c, &key));
}

TEST("memo: lookup finds complete entry and increments hits")
{
    MemoCache c;
    memo_init(&c);

    ensure_init();
    AtomId aid = atom_intern(&g_atoms, "complete_pred");
    TermRef goal = term_make_atom(&g_arena, aid);

    MemoKey key;
    REQUIRE(memo_key_from_goal(&key, goal, &g_arena, &g_vars));

    MemoEntry *e = memo_begin(&c, &key);
    REQUIRE(e != nullptr);
    memo_complete(e);

    const MemoEntry *found = memo_lookup(&c, &key);
    REQUIRE(found != nullptr);
    EXPECT_EQ(c.hits, 1ULL);
}

TEST("memo: add_solution stores args and increments soln_count")
{
    MemoCache c;
    memo_init(&c);

    ensure_init();
    AtomId fid  = atom_intern(&g_atoms, "color");
    AtomId r_id = atom_intern(&g_atoms, "red");
    AtomId g_id = atom_intern(&g_atoms, "green");

    TermRef goal_args[1] = { term_make_atom(&g_arena, r_id) };
    TermRef goal = term_make_compound(&g_arena, fid, 1U, goal_args);

    MemoKey key;
    REQUIRE(memo_key_from_goal(&key, goal, &g_arena, &g_vars));

    MemoEntry *e = memo_begin(&c, &key);
    REQUIRE(e != nullptr);

    MemoArgSlot sol1[1] = {{ MEMO_ARG_ATOM, {r_id} }};
    MemoArgSlot sol2[1] = {{ MEMO_ARG_ATOM, {g_id} }};

    EXPECT_EQ(memo_add_solution(&c, e, sol1, 1U), 0);
    EXPECT_EQ(memo_add_solution(&c, e, sol2, 1U), 0);
    memo_complete(e);

    EXPECT_EQ(e->soln_count, 2U);
    EXPECT_EQ(c.arg_pool_count, 2U);
}

TEST("memo: invalidate resets all entries")
{
    MemoCache c;
    memo_init(&c);

    ensure_init();
    AtomId aid = atom_intern(&g_atoms, "inv_pred");
    TermRef goal = term_make_atom(&g_arena, aid);

    MemoKey key;
    REQUIRE(memo_key_from_goal(&key, goal, &g_arena, &g_vars));

    MemoEntry *e = memo_begin(&c, &key);
    REQUIRE(e != nullptr);
    memo_complete(e);

    EXPECT_NOTNULL(memo_lookup(&c, &key));

    memo_invalidate(&c);

    /* After invalidation, no entry should be found */
    EXPECT_NULL(memo_lookup(&c, &key));
    EXPECT_EQ(c.entry_count,    0U);
    EXPECT_EQ(c.arg_pool_count, 0U);
}

TEST("memo: miss counter increments on failed lookup")
{
    MemoCache c;
    memo_init(&c);

    ensure_init();
    AtomId aid = atom_intern(&g_atoms, "never_stored");
    TermRef goal = term_make_atom(&g_arena, aid);

    MemoKey key;
    REQUIRE(memo_key_from_goal(&key, goal, &g_arena, &g_vars));

    memo_lookup(&c, &key);
    memo_lookup(&c, &key);
    EXPECT_EQ(c.misses, 2ULL);
    EXPECT_EQ(c.hits,   0ULL);
}

TEST("memo: null guard — init returns -1 for null")
{
    EXPECT_EQ(memo_init(nullptr), -1);
}

