/*
 * epilog_ffi.h — C-linkage public API for the Epilog inference engine.
 *
 * This header is pure C (C99+) and intentionally exposes no C++ types.
 * Consumers: C, Python (ctypes/cffi), Odin, and any other language that
 * can load a shared library and call C ABI functions.
 *
 * Lifecycle
 * ---------
 *   1. epilog_create()          — allocate + init an engine instance
 *   2. epilog_load_string()     — add Prolog facts/rules from a source string
 *   3. epilog_query()           — run a query; iterate via callback
 *   4. epilog_destroy()         — free all resources
 *
 * Thread safety
 * -------------
 *   Each EpilogEngine is independent.  Do NOT share one instance across
 *   threads concurrently.  Multiple instances in separate threads is fine.
 *
 * Error codes
 * -----------
 *   All functions that can fail return int.
 *   0  = success
 *  -1  = general error / bad argument
 *  -2  = capacity overflow (too many facts, atoms, etc.)
 *  -3  = parse error
 *
 * Solution callback
 * -----------------
 *   epilog_query() calls your callback once per solution.
 *   Return EPILOG_NEXT to ask for the next solution.
 *   Return EPILOG_STOP to stop early (like Prolog's !).
 *
 * Term inspection
 * ---------------
 *   Inside the callback, use epilog_soln_* to inspect bound values.
 *   EpilogVarIter lets you walk over the variables in the query.
 */

#ifndef EPILOG_FFI_H
#define EPILOG_FFI_H

#include <stdint.h>
#include <stddef.h>

#ifdef __cplusplus
extern "C" {
#endif

/* ---- Opaque engine handle ------------------------------------------------ */

typedef struct EpilogEngine EpilogEngine;

/* ---- Callback return codes ----------------------------------------------- */

typedef enum EpilogSignal {
    EPILOG_NEXT = 0,   /* continue: ask for more solutions */
    EPILOG_STOP = 1    /* stop: do not produce further solutions */
} EpilogSignal;

/* ---- Term kinds ----------------------------------------------------------- */

typedef enum EpilogTermKind {
    EPILOG_TERM_ATOM     = 1,
    EPILOG_TERM_VAR      = 2,
    EPILOG_TERM_COMPOUND = 3,
    EPILOG_TERM_INT      = 4,
    EPILOG_TERM_UNBOUND  = 5   /* variable with no binding */
} EpilogTermKind;

/* ---- Solution handle (valid only inside the callback) -------------------- */

typedef struct EpilogSolution EpilogSolution;

/* ---- Solution callback type --------------------------------------------- */

/*
 * EpilogCallback — called once per solution.
 *
 *   soln     — opaque handle; valid only for the duration of this call
 *   userdata — the pointer you passed to epilog_query()
 *
 * Return EPILOG_NEXT to request the next solution, EPILOG_STOP to halt.
 */
typedef EpilogSignal (*EpilogCallback)(const EpilogSolution *soln,
                                       void                 *userdata);

/* ---- Engine lifecycle ---------------------------------------------------- */

/*
 * epilog_create — allocate and initialise a new engine instance.
 * Returns nullptr on allocation failure (extremely unlikely given static arenas).
 */
EpilogEngine *epilog_create(void);

/* epilog_destroy — release all resources held by the engine. */
void epilog_destroy(EpilogEngine *engine);

/* ---- Loading facts and rules --------------------------------------------- */

/*
 * epilog_load_string — parse and assert all clauses in src.
 *
 *   src   — NUL-terminated Prolog source ("parent(alice,bob). ...")
 *
 * Returns the number of clauses asserted, or a negative error code.
 */
int epilog_load_string(EpilogEngine *engine, const char *src);

/* ---- Running queries ------------------------------------------------------ */

/*
 * epilog_query — execute a query goal and enumerate solutions.
 *
 *   goal_src — NUL-terminated goal string WITHOUT the "?- " prefix and
 *              WITHOUT the trailing ".".  Examples:
 *                  "grandparent(alice, carol)"
 *                  "color(X)"
 *   cb       — called once per solution; may be NULL (just count solutions)
 *   userdata — passed unchanged to cb
 *
 * Returns the total number of solutions found, or a negative error code.
 */
int epilog_query(EpilogEngine *engine, const char *goal_src,
                 EpilogCallback cb, void *userdata);

/* ---- Inspecting solutions ------------------------------------------------ */

/*
 * epilog_soln_var_count — number of query variables in the solution.
 */
uint32_t epilog_soln_var_count(const EpilogSolution *soln);

/*
 * epilog_soln_var_name — name of the i-th query variable (0-based).
 * Returns nullptr if i is out of range.
 * The returned pointer is valid only for the duration of the callback.
 */
const char *epilog_soln_var_name(const EpilogSolution *soln, uint32_t i);

/*
 * epilog_soln_var_kind — EpilogTermKind of the i-th variable's binding.
 * Returns EPILOG_TERM_UNBOUND if unbound.
 */
EpilogTermKind epilog_soln_var_kind(const EpilogSolution *soln, uint32_t i);

/*
 * epilog_soln_var_atom — NUL-terminated spelling of an atom binding.
 * Returns nullptr if the variable is not bound to an atom.
 * Valid only for the duration of the callback.
 */
const char *epilog_soln_var_atom(const EpilogSolution *soln, uint32_t i);

/*
 * epilog_soln_var_int — integer value of an integer binding.
 * Sets *ok to 1 on success, 0 if not an integer.
 */
int32_t epilog_soln_var_int(const EpilogSolution *soln, uint32_t i, int *ok);

/*
 * epilog_soln_var_functor — for compound bindings, the functor spelling.
 * Returns nullptr if not a compound term.
 * Valid only for the duration of the callback.
 */
const char *epilog_soln_var_functor(const EpilogSolution *soln, uint32_t i);

/*
 * epilog_soln_var_arity — for compound bindings, the arity.
 * Returns 0 if not a compound term.
 */
uint8_t epilog_soln_var_arity(const EpilogSolution *soln, uint32_t i);

/* ---- Statistics ---------------------------------------------------------- */

/*
 * epilog_stats_call_count — how many times (functor/arity) has been queried.
 * Returns 0 if not tracked (including unknown predicate).
 */
uint64_t epilog_stats_call_count(const EpilogEngine *engine,
                                  const char *functor, uint8_t arity);

/*
 * epilog_stats_soln_count — total solutions produced for (functor/arity).
 */
uint64_t epilog_stats_soln_count(const EpilogEngine *engine,
                                  const char *functor, uint8_t arity);

/* epilog_stats_reset — zero all counters. */
void epilog_stats_reset(EpilogEngine *engine);

/* ---- Version -------------------------------------------------------------- */

/* epilog_version_string — returns e.g. "0.2.0". Pointer is static; do not free. */
const char *epilog_version_string(void);

#ifdef __cplusplus
} /* extern "C" */
#endif

#endif /* EPILOG_FFI_H */

/*
 * epilog_ffi.cpp — C-linkage wrapper over the Epilog inference engine.
 *
 * Implements the API declared in epilog_ffi.h.  All internal C++ types are
 * hidden behind EpilogEngine and EpilogSolution, which are opaque to callers.
 */

#include "../include/epilog_ffi.h"
#include "../include/atoms.hpp"
#include "../include/variables.hpp"
#include "../include/terms.hpp"
#include "../include/lexer.hpp"
#include "../include/parser.hpp"
#include "../include/database.hpp"
#include "../include/unifier.hpp"
#include "../include/solver.hpp"
#include "../include/builtins.hpp"
#include "../include/stats.hpp"

#include <cstdlib>
#include <cstring>
#include <new>

/* ---- EpilogEngine -------------------------------------------------------- */

struct EpilogEngine {
    AtomTable   atoms       = {};
    Database    db          = {};
    TermArena   clause_arena = {};
    VarRegistry clause_vars  = {};
    QueryStats  stats        = {};
};

/* ---- EpilogSolution ------------------------------------------------------ */

/*
 * A solution snapshot: for each query variable we store its name and its
 * resolved binding (kind + value).  This is populated from the SolverEnv
 * inside the solve callback before handing off to user code.
 */

constexpr uint32_t FFI_MAX_VARS = VAR_REGISTRY_CAPACITY;

struct SolnVar {
    char           name[VAR_NAME_MAX_LEN + 1U];
    EpilogTermKind kind    = EPILOG_TERM_UNBOUND;
    AtomId         atom_id = ATOM_ID_INVALID;   /* TERM_ATOM */
    int32_t        int_val = 0;                  /* TERM_INT  */
    AtomId         functor = ATOM_ID_INVALID;   /* TERM_COMPOUND */
    uint8_t        arity   = 0U;                 /* TERM_COMPOUND */
};

struct EpilogSolution {
    const AtomTable *atoms    = nullptr;
    SolnVar          vars[FFI_MAX_VARS];
    uint32_t         var_count = 0U;
};

/* ---- Internal helpers ---------------------------------------------------- */

/*
 * resolve_term — walk the term/variable chain and classify into SolnVar.
 */
static void resolve_term(SolnVar *out, TermRef ref,
                         const TermArena *arena, const VarRegistry *vars,
                         const AtomTable *atoms)
{
    /* Follow variable bindings */
    for (uint32_t step = 0U; step < VAR_REGISTRY_CAPACITY; ++step) {
        const Term *t = term_get(arena, ref);
        if (t == nullptr) { out->kind = EPILOG_TERM_UNBOUND; return; }

        switch (t->kind) {
            case TERM_KIND_ATOM:
                out->kind    = EPILOG_TERM_ATOM;
                out->atom_id = t->data.atom_id;
                return;
            case TERM_KIND_INT:
                out->kind    = EPILOG_TERM_INT;
                out->int_val = t->data.int_val;
                return;
            case TERM_KIND_COMPOUND:
                out->kind    = EPILOG_TERM_COMPOUND;
                out->functor = t->data.compound.functor;
                out->arity   = t->data.compound.arity;
                return;
            case TERM_KIND_VAR: {
                WalkResult wr = var_walk(vars, t->data.var.var_id);
                if (wr.tag == TERM_UNBOUND) {
                    out->kind = EPILOG_TERM_UNBOUND;
                    return;
                }
                if (wr.tag == TERM_TERMREF) {
                    ref = wr.value.term_ref;
                    break;
                }
                if (wr.tag == TERM_ATOM) {
                    out->kind    = EPILOG_TERM_ATOM;
                    out->atom_id = wr.value.atom_id;
                    return;
                }
                out->kind = EPILOG_TERM_UNBOUND;
                return;
            }
            default:
                out->kind = EPILOG_TERM_UNBOUND;
                return;
        }
    }
    (void)atoms;
    out->kind = EPILOG_TERM_UNBOUND;
}

/* ---- Internal query state passed through solve callback ------------------ */

struct QueryCtx {
    EpilogEngine   *engine       = nullptr;
    EpilogCallback  user_cb      = nullptr;
    void           *user_data    = nullptr;
    EpilogSolution  soln         = {};
    const TermArena *query_arena = nullptr;
    const VarRegistry *query_vars = nullptr;
    AtomId          top_functor  = ATOM_ID_INVALID;
    uint8_t         top_arity    = 0U;
    uint32_t        solutions    = 0U;
};

static SolveSignal ffi_solve_callback(SolverEnv *env,
                                      const TermRef *goals,
                                      uint32_t goal_count,
                                      void *userdata)
{
    (void)goals; (void)goal_count;
    QueryCtx *qctx = static_cast<QueryCtx *>(userdata);

    /* Build solution snapshot */
    EpilogSolution *soln = &qctx->soln;
    soln->atoms     = &qctx->engine->atoms;
    soln->var_count = 0U;

    for (uint32_t i = 0U; i < env->vars->count && soln->var_count < FFI_MAX_VARS; ++i) {
        const VarEntry *ve = &env->vars->entries[i];
        if (ve->id == VAR_ID_INVALID) { continue; }

        /* Skip anonymous variables */
        if (ve->name[0] == '_' && ve->name[1] == '\0') { continue; }
        /* Skip internal rename copies (contain '#' or other non-alpha prefix) */
        if (ve->name[0] == '\0') { continue; }

        SolnVar *sv = &soln->vars[soln->var_count];
        memset(sv, 0, sizeof(SolnVar));
        strncpy(sv->name, ve->name, VAR_NAME_MAX_LEN);
        sv->name[VAR_NAME_MAX_LEN] = '\0';

        /* Resolve binding */
        if (ve->tag == TERM_UNBOUND) {
            sv->kind = EPILOG_TERM_UNBOUND;
        } else if (ve->tag == TERM_ATOM) {
            sv->kind    = EPILOG_TERM_ATOM;
            sv->atom_id = ve->value.atom_id;
        } else if (ve->tag == TERM_TERMREF) {
            TermRef bound_ref = ve->value.term_ref;
            resolve_term(sv, bound_ref, env->arena, env->vars, &qctx->engine->atoms);
        } else {
            sv->kind = EPILOG_TERM_UNBOUND;
        }

        soln->var_count++;
    }

    qctx->solutions++;

    if (qctx->user_cb == nullptr) { return SOLVE_NEXT; }

    EpilogSignal sig = qctx->user_cb(soln, qctx->user_data);
    return (sig == EPILOG_STOP) ? SOLVE_STOP : SOLVE_NEXT;
}

/* ---- Public API ---------------------------------------------------------- */

EpilogEngine *epilog_create(void)
{
    void *mem = malloc(sizeof(EpilogEngine));
    if (mem == nullptr) { return nullptr; }
    EpilogEngine *e = new (mem) EpilogEngine();
    atom_table_init(&e->atoms);
    db_init(&e->db);
    term_arena_init(&e->clause_arena);
    var_registry_init(&e->clause_vars);
    stats_init(&e->stats);
    return e;
}

void epilog_destroy(EpilogEngine *engine)
{
    if (engine == nullptr) { return; }
    engine->~EpilogEngine();
    free(engine);
}

int epilog_load_string(EpilogEngine *engine, const char *src)
{
    if (engine == nullptr || src == nullptr) { return -1; }

    static TokenList toks;
    memset(&toks, 0, sizeof(toks));
    if (lex(src, &toks) < 0) { return -3; }

    var_registry_init(&engine->clause_vars);

    Parser p;
    if (parser_init(&p, &toks, &engine->clause_arena,
                    &engine->atoms, &engine->clause_vars) < 0) { return -3; }

    int n = 0;
    ParsedClause c;
    for (;;) {
        memset(&c, 0, sizeof(c));
        ParseResult r = parser_next_clause(&p, &c);
        if (r == PARSE_EOF) { break; }
        if (r != PARSE_OK)  { return -3; }
        int rc = db_assert_last(&engine->db, &c, &engine->clause_arena);
        if (rc < 0) { return -2; }
        n++;
    }
    return n;
}

int epilog_query(EpilogEngine *engine, const char *goal_src,
                 EpilogCallback cb, void *userdata)
{
    if (engine == nullptr || goal_src == nullptr) { return -1; }

    /* Wrap goal_src in "?- <goal>." for the parser */
    static char buf[4096];
    int written = snprintf(buf, sizeof(buf), "?- %s.", goal_src);
    if (written < 0 || static_cast<size_t>(written) >= sizeof(buf)) { return -1; }

    static TokenList toks;
    memset(&toks, 0, sizeof(toks));
    if (lex(buf, &toks) < 0) { return -3; }

    static TermArena   query_arena;
    static VarRegistry query_vars;
    term_arena_init(&query_arena);
    var_registry_init(&query_vars);

    Parser p;
    if (parser_init(&p, &toks, &query_arena, &engine->atoms, &query_vars) < 0) {
        return -3;
    }
    ParsedQuery pq;
    if (parser_query(&p, &pq) != PARSE_OK) { return -3; }
    if (pq.goal_count == 0U) { return 0; }

    /* Determine top-level functor for stats */
    AtomId  top_functor = ATOM_ID_INVALID;
    uint8_t top_arity   = 0U;
    if (pq.goal_count >= 1U) {
        const Term *gt = term_get(&query_arena, pq.goals[0]);
        if (gt != nullptr) {
            if (gt->kind == TERM_KIND_ATOM) {
                top_functor = gt->data.atom_id; top_arity = 0U;
            } else if (gt->kind == TERM_KIND_COMPOUND) {
                top_functor = gt->data.compound.functor;
                top_arity   = gt->data.compound.arity;
            }
        }
    }
    if (top_functor != ATOM_ID_INVALID) {
        stats_record_call(&engine->stats, top_functor, top_arity);
    }

    SolverEnv env;
    solver_env_init(&env, &query_arena, &engine->clause_arena,
                    &query_vars, &engine->clause_vars,
                    &engine->atoms, &engine->db);

    QueryCtx qctx;
    qctx.engine       = engine;
    qctx.user_cb      = cb;
    qctx.user_data    = userdata;
    qctx.query_arena  = &query_arena;
    qctx.query_vars   = &query_vars;
    qctx.top_functor  = top_functor;
    qctx.top_arity    = top_arity;
    qctx.solutions    = 0U;
    qctx.soln.atoms   = &engine->atoms;

    solve(&env, pq.goals, pq.goal_count, ffi_solve_callback, &qctx);

    if (top_functor != ATOM_ID_INVALID) {
        stats_record_solutions(&engine->stats, top_functor, top_arity,
                               static_cast<uint64_t>(qctx.solutions));
    }

    return static_cast<int>(qctx.solutions);
}

/* ---- Solution inspection ------------------------------------------------- */

uint32_t epilog_soln_var_count(const EpilogSolution *soln)
{
    if (soln == nullptr) { return 0U; }
    return soln->var_count;
}

const char *epilog_soln_var_name(const EpilogSolution *soln, uint32_t i)
{
    if (soln == nullptr || i >= soln->var_count) { return nullptr; }
    return soln->vars[i].name;
}

EpilogTermKind epilog_soln_var_kind(const EpilogSolution *soln, uint32_t i)
{
    if (soln == nullptr || i >= soln->var_count) { return EPILOG_TERM_UNBOUND; }
    return soln->vars[i].kind;
}

const char *epilog_soln_var_atom(const EpilogSolution *soln, uint32_t i)
{
    if (soln == nullptr || i >= soln->var_count) { return nullptr; }
    const SolnVar *sv = &soln->vars[i];
    if (sv->kind != EPILOG_TERM_ATOM)    { return nullptr; }
    if (soln->atoms == nullptr)          { return nullptr; }
    return atom_spelling(soln->atoms, sv->atom_id);
}

int32_t epilog_soln_var_int(const EpilogSolution *soln, uint32_t i, int *ok)
{
    if (ok != nullptr) { *ok = 0; }
    if (soln == nullptr || i >= soln->var_count) { return 0; }
    const SolnVar *sv = &soln->vars[i];
    if (sv->kind != EPILOG_TERM_INT) { return 0; }
    if (ok != nullptr) { *ok = 1; }
    return sv->int_val;
}

const char *epilog_soln_var_functor(const EpilogSolution *soln, uint32_t i)
{
    if (soln == nullptr || i >= soln->var_count) { return nullptr; }
    const SolnVar *sv = &soln->vars[i];
    if (sv->kind != EPILOG_TERM_COMPOUND) { return nullptr; }
    if (soln->atoms == nullptr)           { return nullptr; }
    return atom_spelling(soln->atoms, sv->functor);
}

uint8_t epilog_soln_var_arity(const EpilogSolution *soln, uint32_t i)
{
    if (soln == nullptr || i >= soln->var_count) { return 0U; }
    const SolnVar *sv = &soln->vars[i];
    if (sv->kind != EPILOG_TERM_COMPOUND) { return 0U; }
    return sv->arity;
}

/* ---- Statistics ---------------------------------------------------------- */

uint64_t epilog_stats_call_count(const EpilogEngine *engine,
                                  const char *functor, uint8_t arity)
{
    if (engine == nullptr || functor == nullptr) { return 0ULL; }
    AtomId id = atom_lookup(&engine->atoms, functor);
    if (id == ATOM_ID_INVALID) { return 0ULL; }
    const QueryStat *e = stats_get(&engine->stats, id, arity);
    return (e != nullptr) ? e->call_count : 0ULL;
}

uint64_t epilog_stats_soln_count(const EpilogEngine *engine,
                                  const char *functor, uint8_t arity)
{
    if (engine == nullptr || functor == nullptr) { return 0ULL; }
    AtomId id = atom_lookup(&engine->atoms, functor);
    if (id == ATOM_ID_INVALID) { return 0ULL; }
    const QueryStat *e = stats_get(&engine->stats, id, arity);
    return (e != nullptr) ? e->soln_count : 0ULL;
}

void epilog_stats_reset(EpilogEngine *engine)
{
    if (engine != nullptr) { stats_reset(&engine->stats); }
}

/* ---- Version ------------------------------------------------------------- */

const char *epilog_version_string(void)
{
    return "0.2.0";
}

